//! Canonical tool identity.
//!
//! `ToolId`, its wire names, family, CLI-only and beta policy are generated by
//! build.rs from the embedded contract (core `TOOL_POLICIES`); this module only
//! adds runtime-owned behavior on top.

use std::str::FromStr;

/// Family used to partition cursor scope digests and remote/local policy.
///
/// Toggling local-only config (e.g. `allowed_paths`) must not invalidate
/// GitHub/remote cursors, so each family scopes its digest differently.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ToolFamily {
    /// Local-filesystem tools: scoped by cwd, allowed paths, and LSP config.
    Local,
    /// GitHub API tools: scoped by API endpoint + home, not local config.
    GitHub,
    /// Other remote tools (artifact, clasify): scoped by home only.
    Remote,
}

include!(concat!(env!("OUT_DIR"), "/tool_ids.rs"));

/// The contract's exit class of `code` (`errorCodes`). An undeclared code,
/// which the output contract already rejects, is an execution failure.
#[must_use]
pub fn error_class(code: &str) -> error_codes::ErrorClass {
    error_codes::parse(code).map_or(error_codes::ErrorClass::Execution, error_codes::class)
}

/// The declared `errorCode` of a row's `data`; `None` when it has none (or
/// an undeclared one, which the output contract already rejects).
#[must_use]
pub(crate) fn error_code_of(
    data: &serde_json::Value,
) -> Option<octocode_contract_types::ErrorCode> {
    data.get("errorCode")
        .and_then(serde_json::Value::as_str)
        .and_then(error_codes::parse)
}

impl ToolId {
    /// Resolve a wire name to its identity, or `None` for an unknown tool.
    #[must_use]
    pub fn from_name(name: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|id| id.as_str() == name)
    }

    /// A local-filesystem tool (honours local policy + allowed paths).
    #[must_use]
    pub(crate) const fn is_local(self) -> bool {
        matches!(self.family(), ToolFamily::Local)
    }

    /// A GitHub API tool (includes `ghCloneRepo`; clone has an extra gate).
    #[must_use]
    pub(crate) const fn is_github(self) -> bool {
        matches!(self.family(), ToolFamily::GitHub)
    }

    /// The public semantic assessment tool (beta plus a non-blank provider key).
    #[must_use]
    pub(crate) const fn is_clasify(self) -> bool {
        matches!(self, Self::Clasify)
    }

    /// Independent queries may execute concurrently; clasify owns its bounded scheduler.
    /// Clone rows run at once: each holds its entry's lock for all of its
    /// work (a cache hit or a fresh checkout, until the row returns), the
    /// lock other processes share, so rows for one entry serialize; eviction
    /// removes only entries whose lock it takes, so it never deletes another
    /// row's checkout; stages, askpass helpers and their names are per row.
    #[must_use]
    pub(crate) const fn supports_concurrent_queries(self) -> bool {
        !matches!(self, Self::Clasify)
    }

    /// Each row carries one source `content` string a caller copies from
    /// (numbered lines, sized to its share of the response page).
    #[must_use]
    pub(crate) const fn reads_source(self) -> bool {
        matches!(self, Self::LocalFetch | Self::GhGetFileContent)
    }

    /// Whether `classification` selects this tool's rows at the shared response
    /// boundary, over one sanitized provider page (code search), instead of
    /// before the tool's own source pagination.
    #[must_use]
    pub(crate) const fn selects_provider_page(self) -> bool {
        matches!(self, Self::GhSearchCode)
    }

    /// Shared row definitions carried by the first display fragment only:
    /// clasify rows are keyed query results that state their questions once.
    #[must_use]
    pub(crate) const fn first_fragment_fields(self) -> &'static [&'static str] {
        match self {
            Self::Clasify => &["/data/questions"],
            _ => &[],
        }
    }
}

impl FromStr for ToolId {
    type Err = ();

    fn from_str(value: &str) -> Result<Self, Self::Err> {
        Self::from_name(value).ok_or(())
    }
}

impl std::fmt::Display for ToolId {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(self.as_str())
    }
}

/// The name of the `index`th (from 0) continuation of `kind` on one row:
/// `kind` itself, then `kind2`, `kind3`, …; [`kind`] is its inverse.
pub(crate) fn numbered(kind: &str, index: usize) -> String {
    match index {
        0 => kind.to_owned(),
        index => format!("{kind}{}", index + 1),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// GitHub routing sees exactly the contract's `github` family.
    #[test]
    fn the_github_identity_covers_exactly_the_github_family() {
        for id in ToolId::ALL {
            assert_eq!(id.github().is_some(), id.is_github(), "{}", id.as_str());
        }
    }

    fn contract_tools() -> &'static [serde_json::Value] {
        crate::contracts::parsed_contract().expect("contract")["tools"]
            .as_array()
            .expect("tools[]")
    }

    #[test]
    fn numbered_names_repeat_their_kind() {
        let names = (0..3)
            .map(|index| numbered("readHits", index))
            .collect::<Vec<_>>();
        assert_eq!(names, ["readHits", "readHits2", "readHits3"]);
    }

    #[test]
    fn names_round_trip_and_are_unique() {
        let mut seen = std::collections::HashSet::new();
        for id in ToolId::ALL {
            assert!(seen.insert(id.as_str()), "duplicate name {}", id.as_str());
            assert_eq!(ToolId::from_name(id.as_str()), Some(id));
            assert_eq!(id.as_str().parse::<ToolId>(), Ok(id));
        }
        assert_eq!(ToolId::from_name("nope"), None);
        assert!("nope".parse::<ToolId>().is_err());
        assert_eq!(ToolId::from_name("semanticAssess"), None);
    }

    #[test]
    fn identity_and_policy_match_the_embedded_contract() {
        let tools = contract_tools();
        assert_eq!(tools.len(), ToolId::ALL.len());
        for (tool, id) in tools.iter().zip(ToolId::ALL) {
            assert_eq!(tool["name"], id.as_str());
            let family = match id.family() {
                ToolFamily::Local => "local",
                ToolFamily::GitHub => "github",
                ToolFamily::Remote => "remote",
            };
            assert_eq!(tool["family"], family, "{id}");
            assert_eq!(tool["beta"], id.is_beta(), "{id}");
            assert_eq!(tool["title"], id.title(), "{id}");
            assert_eq!(
                crate::contracts::tool_contract(id).expect("tool contract"),
                tool,
                "{id}"
            );
        }
    }
}
